document.addEventListener("DOMContentLoaded",function(){const toggler=document.getElementById("theme-toggler");const HTML=document.getElementsByTagName("html")[0];const body=document.body;const selectors=body.querySelectorAll(".font-size-selector span");const FONT_CLASSES=["font-size-normal","font-size-medium","font-size-big"];toggler.checked=HTML.dataset.theme==="dark";console.log(HTML.dataset.theme);console.log(HTML.dataset.size);Cookies.set("theme",HTML.dataset.theme);Cookies.set("size",HTML.dataset.size);toggler.addEventListener("click",()=>{HTML.dataset.theme=toggler.checked?"dark":"light";console.log(HTML.dataset.theme);Cookies.set("theme",HTML.dataset.theme)});function applyFontSize(newSize){HTML.classList.remove(...FONT_CLASSES);HTML.classList.add(newSize);Cookies.set("size",newSize);let old_selection=body.querySelector(".font-size-selector span.selected");if(old_selection){old_selection.classList.remove("selected")}let selection=body.querySelector(`.font-size-selector span[data-size=${newSize}]`);if(selection){selection.classList.add("selected")}}if(selectors){for(const selector of selectors){selector.addEventListener("click",event=>{applyFontSize(event.target.dataset.size)})}}applyFontSize(HTML.dataset.size)});
